import{_ as t,o,c as a,a3 as d}from"./chunks/framework.D1GAkLkK.js";const u=JSON.parse('{"title":"Program contract","description":"","frontmatter":{},"headers":[],"relativePath":"reference/program-contract.md","filePath":"reference/program-contract.md"}'),s={name:"reference/program-contract.md"};function i(n,e,r,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="program-contract" tabindex="-1">Program contract <a class="header-anchor" href="#program-contract" aria-label="Permalink to &quot;Program contract&quot;">​</a></h1><p>Every program that OpsTruss runs, from a unit, a task, a step, or a plugin, gets its inputs and gives its results the same way. This page is what a script or a plugin can rely on.</p><h2 id="in" tabindex="-1">In <a class="header-anchor" href="#in" aria-label="Permalink to &quot;In&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What</th><th>Holds</th></tr></thead><tbody><tr><td><code>INPUT_&lt;NAME&gt;</code></td><td>Each input of the task or plugin, in uppercase with <code>-</code> as <code>_</code>; a list or a map as JSON. An input over 64 KiB is only in <code>OPSTRUSS_INPUTS</code></td></tr><tr><td><code>OPSTRUSS_INPUTS</code></td><td>A JSON file with every input in its own type; mode <code>0600</code>, removed after the call</td></tr><tr><td><code>OPSTRUSS_STATE</code></td><td>For a program of a unit: a JSON file with the last outputs and inputs that succeeded, and an attempt that did not finish; for <code>destroy</code>, those of what it takes away</td></tr><tr><td>stdin</td><td>What <code>stdin:</code> writes</td></tr><tr><td>arguments</td><td>For the <code>exec</code> hook only: what follows <code>--</code> in <code>opstruss exec</code></td></tr></tbody></table><p><code>INPUT_*</code> reaches the program that is the body of a task or a plugin. A <code>run</code> inside <code>steps:</code> gets values through <code>env:</code>, so each value reaches only the program that names it.</p><h2 id="out" tabindex="-1">Out <a class="header-anchor" href="#out" aria-label="Permalink to &quot;Out&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What</th><th>Means</th></tr></thead><tbody><tr><td>exit code</td><td>0 is success, anything else failure; a program killed by a signal exits with 128 plus its number, as in a shell</td></tr><tr><td><code>OPSTRUSS_OUTPUT</code></td><td>A file of outputs: <code>name=value</code> lines, <code>name&lt;&lt;EOF</code> … <code>EOF</code> for several lines, or one JSON object, which keeps types</td></tr><tr><td><code>OPSTRUSS_PLAN</code></td><td>For <code>plan</code> only, optional: the changes, the outputs that change, a digest, and whether the plan is exact</td></tr><tr><td><code>OPSTRUSS_RESULT</code></td><td>Optional: <code>{&quot;changed&quot;: false, &quot;message&quot;: &quot;…&quot;, &quot;sensitive&quot;: [&quot;&lt;output&gt;&quot;]}</code>; without <code>changed</code>, the program changed something</td></tr><tr><td>stdout, stderr</td><td>The log of the run; also an output with <code>from: stdout</code> or <code>from: stderr</code></td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>image=ghcr.io/acme/app:1.2</span></span>
<span class="line"><span>notes&lt;&lt;EOF</span></span>
<span class="line"><span>first line</span></span>
<span class="line"><span>second line</span></span>
<span class="line"><span>EOF</span></span></code></pre></div><p>A text value is read by the <code>type</code> of its output, so <code>port=8080</code> is a number for an output of type <code>integer</code>.</p><h2 id="plans" tabindex="-1">Plans <a class="header-anchor" href="#plans" aria-label="Permalink to &quot;Plans&quot;">​</a></h2><p>A plugin&#39;s <code>plan</code> writes <code>$OPSTRUSS_PLAN</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;changes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;create&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;resource&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;web&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sensitive&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;outputs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;services&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;digest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;exact&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>action</code> is <code>create</code>, <code>update</code>, <code>delete</code>, <code>replace</code>, or <code>run</code>.</li><li><code>digest</code> is a hash of what will be applied, the actions and their values, not of a plan file: the same for the same state and inputs, so a plan made again in another run matches. OpsTruss joins it with the digest of the definition of the unit.</li><li><code>exact: true</code> is a promise: <code>up</code> applies exactly the changes whose digest is <code>$OPSTRUSS_DIGEST</code>, from a plan it kept in <code>OPSTRUSS_WORKDIR</code> or <code>OPSTRUSS_TEMP</code>, or fails when a new plan differs, as a saved plan of Terraform. A plugin that cannot promise it writes <code>exact: false</code>, and an approval holds only for an exact plan.</li><li>A plan that writes nothing means that the unit runs.</li></ul><h2 id="where" tabindex="-1">Where <a class="header-anchor" href="#where" aria-label="Permalink to &quot;Where&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Is</th></tr></thead><tbody><tr><td>working directory</td><td>The directory of the file that writes the unit or task, or its <code>dir:</code></td></tr><tr><td><code>OPSTRUSS_PLUGIN_DIR</code></td><td>The directory of the plugin; for programs of plugins only</td></tr><tr><td><code>OPSTRUSS_WORKDIR</code></td><td>The work directory of the unit, used under its lock; a cache that may be empty at any call, as in CI, except between <code>plan</code> and <code>up</code> of the same turn</td></tr><tr><td><code>OPSTRUSS_ARTIFACTS</code></td><td>A directory for files that the record of the run keeps</td></tr><tr><td><code>OPSTRUSS_TEMP</code></td><td>The temporary directory of the run, shared by its programs; removed when the run ends</td></tr><tr><td><code>OPSTRUSS_STATE_DIR</code></td><td>For a plugin with <code>state: tool</code> on the local backend: the <code>tool/</code> directory of the unit</td></tr><tr><td><code>OPSTRUSS_STATE_KEY</code></td><td>The lasting identity of a unit, such as <code>prod/zone.7f3a9c1e</code>, which stays when the unit moves; empty in the plan of a unit without a record</td></tr></tbody></table><h2 id="facts" tabindex="-1">Facts <a class="header-anchor" href="#facts" aria-label="Permalink to &quot;Facts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Is</th></tr></thead><tbody><tr><td><code>OPSTRUSS_PROJECT</code>, <code>OPSTRUSS_STACK</code></td><td>The project and the stack</td></tr><tr><td><code>OPSTRUSS_ADDRESS</code></td><td>The address of the unit, such as <code>prod/web</code></td></tr><tr><td><code>OPSTRUSS_TASK</code>, <code>OPSTRUSS_RUN</code></td><td>The task, and the id of the run</td></tr><tr><td><code>OPSTRUSS_RUN_PARENTS</code></td><td>The ids of the runs that started this one, nearest last</td></tr><tr><td><code>OPSTRUSS_REASON</code></td><td>Why the unit runs: <code>changed</code>, <code>requested</code>, <code>forced</code>, or <code>interrupted</code> for one whose last attempt did not finish; a value it does not know reads as <code>changed</code></td></tr><tr><td><code>OPSTRUSS_DIGEST</code></td><td>The digest of the plan that was approved</td></tr><tr><td><code>OPSTRUSS_SERVICE_ID</code></td><td>For a program that the daemon keeps running: an id that its children carry too</td></tr><tr><td><code>OPSTRUSS_CONTRACT</code></td><td>The version of this contract, <code>1</code>; it goes up only for a change that breaks programs</td></tr></tbody></table><p>Not every program runs inside a run or for a unit:</p><ul><li>Every program gets the environment below, <code>OPSTRUSS_CONTRACT</code>, <code>OPSTRUSS_PROJECT</code>, and <code>OPSTRUSS_STACK</code>.</li><li>A program that ends inside a run, as a task, a step, a <code>run</code> unit, or a secret source, also gets <code>OPSTRUSS_RUN</code>, <code>OPSTRUSS_RUN_PARENTS</code>, <code>OPSTRUSS_TASK</code>, <code>OPSTRUSS_REASON</code>, <code>OPSTRUSS_TEMP</code>, the contract files, and <code>OPSTRUSS_ARTIFACTS</code>, except a secret source.</li><li>A program of a unit gets <code>OPSTRUSS_ADDRESS</code> and <code>OPSTRUSS_STATE_KEY</code>; one under the lock of the unit, as <code>plan</code>, <code>up</code>, <code>destroy</code>, and the <code>exec</code> hook, also gets <code>OPSTRUSS_WORKDIR</code>, <code>OPSTRUSS_STATE</code>, and <code>OPSTRUSS_STATE_DIR</code>. The <code>status</code> and <code>logs</code> tasks of a plugin run without the lock, so they get <code>OPSTRUSS_STATE</code> and <code>OPSTRUSS_STATE_DIR</code> to read, without <code>OPSTRUSS_WORKDIR</code>.</li><li>A program that lives outside a run, as a service and the source of a <code>watch</code>, gets inputs through <code>INPUT_*</code> only, and <code>OPSTRUSS_SERVICE_ID</code>.</li></ul><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><p>A program starts from a clean environment: <code>PATH</code>, with the binaries of the plugin first, <code>HOME</code>, <code>USER</code>, <code>LANG</code>, <code>LC_*</code>, <code>TZ</code>, <code>TMPDIR</code>, <code>TERM</code>, the proxy variables, <code>SSL_CERT_*</code>, and <code>SSH_AUTH_SOCK</code>. To that come the variables that <code>env:</code> sets, and those of the environment of OpsTruss that <code>pass:</code> lets through; for a plugin, only those that its <code>env:</code> asks for, by name or by pattern. <code>OPSTRUSS_*</code> and <code>INPUT_*</code> come only from OpsTruss: <code>env:</code> cannot set them and <code>pass:</code> never passes them.</p><p>The output of a program is a pipe, not a terminal, so most tools leave out color. OpsTruss sets <code>NO_COLOR=1</code> when the output of the run has no color, or when an output reads the stream of the program; a tool that colors with a flag, as <code>tofu</code>, can color when <code>NO_COLOR</code> is not set. <code>env: {FORCE_COLOR: &quot;1&quot;}</code> asks a tool for color.</p><h2 id="stopping" tabindex="-1">Stopping <a class="header-anchor" href="#stopping" aria-label="Permalink to &quot;Stopping&quot;">​</a></h2><p>At cancel or timeout, <code>stop.signal</code> (SIGINT by default) goes to the process group of the program; after <code>stop.grace</code> (1m by default) the group is killed. Processes left in the group when the program ends, such as <code>server &amp;</code> in a script, are stopped the same way before the lock of the unit is let go, as systemd does with <code>KillMode=control-group</code>.</p><p>The lock of the run is the inherited file descriptor 3, which a shell and Go pass on to children; a run that starts after OpsTruss died waits while a program of the old run still holds it, or still carries <code>OPSTRUSS_RUN=&lt;id&gt;</code> in its environment.</p>`,25)])])}const S=t(s,[["render",i]]);export{u as __pageData,S as default};
